/* Reference Adler-32 (single-shot, no chunking needed for 16 bytes). */
static unsigned long long ref_adler(unsigned seed, const unsigned char *buf)
{
    unsigned a = seed & 0xffffu, b = (seed >> 16) & 0xffffu;
    unsigned i;
    for (i = 0; i < 16; ++i) { a = (a + buf[i]) % 65521u; b = (b + a) % 65521u; }
    return a | ((unsigned long long)b << 16);
}

